      }

    case actions.ActionTypes.VIDEO_PREVIEW_FAIL:
      {
        return Object.assign({}, state, {
          videoPreview: [],
          videoPreviewLoading: false,
          videoPreviewLoaded: false,
          videoPreviewFailed: true
        });
      }
    // <-------------CLEAR VARIANT RELATED VARIABLES--------------> //

    case actions.ActionTypes.CLEAR_VARIANT:
      {
        return Object.assign({}, state, {
          originalProbabiltyArray: [],
          probabiltyOptions: [],
          selectedVariant: [],
          selectedVariantOriginal: [],
          productDetail: {}
        });
      }

    default:
      {
        return state;
      }
  }
} // product list action

